use cpal::traits::{DeviceTrait, HostTrait}; fn main() { let host = cpal::default_host(); let device = host.default_output_device().unwrap(); let config = device.default_output_config().unwrap(); let stream = device.build_input_stream(&config.into(), |_: &[f32], _| {}, |err| {}, None); println!("Stream is_ok: {}", stream.is_ok()); if let Err(e) = stream { println!("Error: {:?}", e); } }
